'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var clipIndex = require( '@stdlib/ndarray/base/clip-index' );
var strided = require( '@stdlib/blas/ext/base/gfirst-index-less-than' ).ndarray;


// MAIN //

/**
* Returns the index of the first element in a one-dimensional ndarray which is less than a corresponding element in another one-dimensional ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* -   When comparing elements, the function checks whether an element in the first one-dimensional input ndarray is less than a corresponding element in the second one-dimensional input ndarray using the less-than operator `<`. As a consequence, comparisons involving `NaN` always evaluate to `false`.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* var vector = require( '@stdlib/ndarray/vector/ctor' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = vector( [ 0.0, 0.0, 0.0, 0.0 ], 'generic' );
* var y = vector( [ 0.0, 0.0, 1.0, 0.0 ], 'generic' );
*
* var fromIndex = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var idx = gfirstIndexLessThan( [ x, y, fromIndex ] );
* // returns 2
*/
function gfirstIndexLessThan( arrays ) {
	var fromIndex;
	var idx;
	var sx;
	var sy;
	var ox;
	var oy;
	var N;
	var x;
	var y;

	x = arrays[ 0 ];
	y = arrays[ 1 ];
	fromIndex = ndarraylike2scalar( arrays[ 2 ] );

	N = numelDimension( x, 0 );
	fromIndex = clipIndex( fromIndex, N );
	if ( fromIndex >= N ) {
		return -1;
	}
	N -= fromIndex;

	sx = getStride( x, 0 );
	ox = getOffset( x ) + ( sx*fromIndex );
	sy = getStride( y, 0 );
	oy = getOffset( y ) + ( sy*fromIndex );

	idx = strided( N, getData( x ), sx, ox, getData( y ), sy, oy );
	if ( idx >= 0 ) {
		idx += fromIndex;
	}
	return idx;
}


// EXPORTS //

module.exports = gfirstIndexLessThan;
